SELECT `l_returnflag`, `l_linestatus`, CASE WHEN COUNT(`l_quantity`) = 0 THEN NULL ELSE COALESCE(SUM(`l_quantity`), 0) END `sum_qty`, CASE WHEN COUNT(`l_extendedprice`) = 0 THEN NULL ELSE COALESCE(SUM(`l_extendedprice`), 0) END `sum_base_price`, CASE WHEN COUNT(`l_extendedprice` * (1 - `l_discount`)) = 0 THEN NULL ELSE COALESCE(SUM(`l_extendedprice` * (1 - `l_discount`)), 0) END `sum_disc_price`, CASE WHEN COUNT(`l_extendedprice` * (1 - `l_discount`) * (1 + `l_tax`)) = 0 THEN NULL ELSE COALESCE(SUM(`l_extendedprice` * (1 - `l_discount`) * (1 + `l_tax`)), 0) END `sum_charge`, CAST(CAST(CASE WHEN COUNT(`l_quantity`) = 0 THEN NULL ELSE COALESCE(SUM(`l_quantity`), 0) END AS DECIMAL(15, 0)) / COUNT(`l_quantity`) AS DECIMAL(15, 0)) `avg_qty`, CAST(CAST(CASE WHEN COUNT(`l_extendedprice`) = 0 THEN NULL ELSE COALESCE(SUM(`l_extendedprice`), 0) END AS DECIMAL(15, 0)) / COUNT(`l_extendedprice`) AS DECIMAL(15, 0)) `avg_price`, CAST(CAST(CASE WHEN COUNT(`l_discount`) = 0 THEN NULL ELSE COALESCE(SUM(`l_discount`), 0) END AS DECIMAL(15, 0)) / COUNT(`l_discount`) AS DECIMAL(15, 0)) `avg_disc`, COUNT(*) `count_order`
FROM `lineitem`
WHERE `l_shipdate` <= DATE '1998-08-27'
GROUP BY `l_returnflag`, `l_linestatus`
ORDER BY `l_returnflag` NULLS LAST, `l_linestatus` NULLS LAST
